<?php
function dr_normalize_doctor_name_v37($name){$name=wp_strip_all_tags((string)$name);$name=preg_replace('/\b(dr|doctor|prof|professor|md|mr|mrs|ms)\.?\b/i','',$name);$name=preg_replace('/\s+/',' ',trim($name));return function_exists('mb_strtolower')?mb_strtolower($name):strtolower($name);}
function dr_get_duplicate_candidates_v37($name,$exclude_id=0,$phone='',$clinic=''){$name=trim($name);if($name==='')return array();$q=new WP_Query(array('post_type'=>'doctor','posts_per_page'=>10,'post__not_in'=>$exclude_id?array((int)$exclude_id):array(),'s'=>$name));$items=array();$target_norm=dr_normalize_doctor_name_v37($name);if($q->have_posts()){while($q->have_posts()){$q->the_post();$pid=get_the_ID();$p_phone=get_post_meta($pid,'phone',true);$p_clinic=get_post_meta($pid,'clinic',true);$p_name_norm=dr_normalize_doctor_name_v37(get_the_title($pid));$score=0;if($p_name_norm===$target_norm)$score+=60;similar_text($p_name_norm,$target_norm,$pct);if($pct>=85)$score+=30;if($phone&&$p_phone&&preg_replace('/\D+/','',$phone)===preg_replace('/\D+/','',$p_phone))$score+=40;if($clinic&&$p_clinic&&strcasecmp(trim($clinic),trim($p_clinic))===0)$score+=25;if($score>=30)$items[]=array('id'=>$pid,'title'=>get_the_title($pid),'designation'=>get_post_meta($pid,'designation',true),'workplace'=>get_post_meta($pid,'workplace',true),'clinic'=>$p_clinic,'phone'=>$p_phone,'district'=>get_post_meta($pid,'district',true),'score'=>$score,'edit'=>get_edit_post_link($pid,''),'view'=>get_permalink($pid));}wp_reset_postdata();}usort($items,function($a,$b){return $b['score']<=>$a['score'];});return $items;}
add_action('add_meta_boxes',function(){add_meta_box('dr_duplicate_check_v37','Duplicate Doctor Check','dr_duplicate_check_box_v37','doctor','side','high');});
function dr_duplicate_check_box_v37($post){$items=dr_get_duplicate_candidates_v37($post->post_title,$post->ID,get_post_meta($post->ID,'phone',true),get_post_meta($post->ID,'clinic',true));echo '<div id="dr-dup-live-box">';if($items){echo '<p style="color:#b45309;font-weight:bold;">⚠️ Similar doctor found:</p>';foreach($items as $it){echo '<div style="border:1px solid #f0d7a1;background:#fff8e1;border-radius:8px;padding:8px;margin-bottom:8px;"><strong>'.esc_html($it['title']).'</strong><br>';if($it['workplace'])echo '<small>🏥 '.esc_html($it['workplace']).'</small><br>';if($it['clinic'])echo '<small>🩺 '.esc_html($it['clinic']).'</small><br>';if($it['district'])echo '<small>📍 '.esc_html($it['district']).'</small><br>';if($it['phone'])echo '<small>📞 '.esc_html($it['phone']).'</small><br>';echo '<a href="'.esc_url($it['edit']).'">Edit</a></div>';}}else echo '<p style="color:#418681;font-weight:bold;">✓ No duplicate found.</p>';echo '</div>';?>
<script>jQuery(function($){var timer=null;$('#title,input[name="phone"],input[name="clinic"]').on('input',function(){clearTimeout(timer);timer=setTimeout(function(){var fd=new FormData();fd.append('action','dr_duplicate_live_check_v37');fd.append('nonce','<?php echo wp_create_nonce('dr_dup_nonce');?>');fd.append('post_id','<?php echo (int)$post->ID;?>');fd.append('title',$('#title').val()||'');fd.append('phone',$('input[name="phone"]').val()||'');fd.append('clinic',$('input[name="clinic"]').val()||'');fetch(ajaxurl,{method:'POST',body:fd}).then(r=>r.text()).then(html=>$('#dr-dup-live-box').html(html));},450);});});</script><?php }
add_action('wp_ajax_dr_duplicate_live_check_v37',function(){if(!current_user_can('edit_posts')||!isset($_POST['nonce'])||!wp_verify_nonce($_POST['nonce'],'dr_dup_nonce'))wp_die('');$post_id=intval($_POST['post_id']??0);$title=sanitize_text_field($_POST['title']??'');$phone=sanitize_text_field($_POST['phone']??'');$clinic=sanitize_text_field($_POST['clinic']??'');$items=dr_get_duplicate_candidates_v37($title,$post_id,$phone,$clinic);if(!$items){echo '<p style="color:#418681;font-weight:bold;">✓ No duplicate found.</p>';wp_die();}echo '<p style="color:#b45309;font-weight:bold;">⚠️ Similar doctor found:</p>';foreach($items as $it){echo '<div style="border:1px solid #f0d7a1;background:#fff8e1;border-radius:8px;padding:8px;margin-bottom:8px;"><strong>'.esc_html($it['title']).'</strong><br>';if($it['workplace'])echo '<small>🏥 '.esc_html($it['workplace']).'</small><br>';if($it['clinic'])echo '<small>🩺 '.esc_html($it['clinic']).'</small><br>';if($it['district'])echo '<small>📍 '.esc_html($it['district']).'</small><br>';if($it['phone'])echo '<small>📞 '.esc_html($it['phone']).'</small><br>';echo '<a href="'.esc_url($it['edit']).'">Edit</a></div>';}wp_die();});
add_action('admin_menu',function(){add_submenu_page('edit.php?post_type=doctor','Duplicate Doctors','Duplicate Doctors','manage_options','dr-duplicates-v37','dr_duplicate_doctors_admin_page_v37');});
function dr_duplicate_doctors_admin_page_v37(){if(isset($_GET['delete_doctor'])&&current_user_can('delete_posts')){$del_id=intval($_GET['delete_doctor']);if(isset($_GET['_wpnonce'])&&wp_verify_nonce($_GET['_wpnonce'],'dr_delete_dup_'.$del_id)){wp_trash_post($del_id);echo '<div class="updated"><p>Doctor moved to Trash.</p></div>';}}$q=new WP_Query(array('post_type'=>'doctor','posts_per_page'=>-1,'post_status'=>'publish','fields'=>'ids'));$groups=array();foreach($q->posts as $pid){$key=dr_normalize_doctor_name_v37(get_the_title($pid));if(!$key)continue;$groups[$key][]=$pid;}$groups=array_filter($groups,function($ids){return count($ids)>1;});?><div class="wrap"><h1>Duplicate Doctors</h1><p>Same/similar doctor names are grouped here. Review details, then edit or move duplicate entries to Trash.</p><?php if(!$groups):?><div class="notice notice-success"><p>No duplicate doctor names found.</p></div><?php else:foreach($groups as $key=>$ids):?><h2>Possible duplicate group: <?php echo esc_html(get_the_title($ids[0]));?> <small>(<?php echo count($ids);?>)</small></h2><table class="widefat striped"><thead><tr><th>Name</th><th>Hospital</th><th>Clinic</th><th>Phone</th><th>District</th><th>Actions</th></tr></thead><tbody><?php foreach($ids as $pid):?><tr><td><strong><?php echo esc_html(get_the_title($pid));?></strong></td><td><?php echo esc_html(get_post_meta($pid,'workplace',true));?></td><td><?php echo esc_html(get_post_meta($pid,'clinic',true));?></td><td><?php echo esc_html(get_post_meta($pid,'phone',true));?></td><td><?php echo esc_html(get_post_meta($pid,'district',true));?></td><td><a class="button" href="<?php echo esc_url(get_edit_post_link($pid));?>">Edit</a> <a class="button button-link-delete" onclick="return confirm('Move this doctor to Trash?')" href="<?php echo esc_url(wp_nonce_url(admin_url('edit.php?post_type=doctor&page=dr-duplicates-v37&delete_doctor='.$pid),'dr_delete_dup_'.$pid));?>">Trash</a></td></tr><?php endforeach;?></tbody></table><?php endforeach;endif;?></div><?php }
